mapper.select:
SELECT EXISTS(
    SELECT 1 FROM fair_reviews WHERE fair_id = #{fairId} AND user_id = #{userId}
)

SELECT 
  FROM fair_reviews
 WHERE fair_id = #{fairId}
   AND user_id = #{userId}

SELECT EXISTS(
    SELECT 1 FROM entry_records WHERE fair_id = #{fairId} AND user_id = #{userId}
)

SELECT fr.review_id, u.nickname, fr.companion_type, fr.visit_purpose, fr.would_revisit, fr.created_at
  FROM fair_reviews fr
  JOIN users u ON u.user_id = fr.user_id
 WHERE fr.fair_id = #{fairId}
 ORDER BY fr.created_at DESC, fr.review_id DESC
 LIMIT #{limit} OFFSET #{offset}

SELECT s.review_id, ft.label FROM fair_review_tag_selections s JOIN feedback_tags ft ON ft.tag_id = s.tag_id AND ft.scope = 'FAIR' WHERE s.review_id IN
#{reviewId}
ORDER BY ft.sort_order
